.row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
}

function makeCounter() {
  let count = 0;
  return function() {
    return ++count;
  }
}

const counter = makeCounter();
counter(); // 1
counter(); // 2

async function getUser(id) {
  try {
    const res = await fetch(`/api/users/${id}`);
    if (!res.ok) throw new Error('Request failed');
    return await res.json();
  } catch (err) {
    console.error(err);
    return null;
  }
}
